import { useStats } from './useStats.js'
import { getChainInfo } from './chainUtils.js'
import { useGuestChain } from './useGuestChain.js'

export default function StatsBar({ mode, sidebar }) {
  const stats = useStats(mode)
  const { activeChainId: chainId } = useGuestChain()
  const { currency } = getChainInfo(chainId)

  const items = stats
    ? mode === 'private'
      ? [
          { l: `TVL (${currency})`, v: stats.tvl },
          { l: 'Total Deposits', v: stats.deposits },
          { l: 'Anonymity Set', v: stats.leaves },
        ]
      : [
          { l: `TVL (${currency})`, v: stats.tvl },
          { l: 'Users', v: stats.users },
          { l: 'Guardian Protected', v: stats.guardianPct },
        ]
    : [
        { l: 'TVL', v: '…' },
        { l: mode === 'private' ? 'Total Deposits' : 'Users', v: '…' },
        { l: mode === 'private' ? 'Anonymity Set' : 'Guardian Protected', v: '…' },
      ]

  if (sidebar) return (
    <>
      {items.map(it => (
        <div key={it.l} className="sidebar-stat-row">
          <span className="sidebar-stat-label">{it.l}</span>
          <span className="sidebar-stat-value">{it.v}</span>
        </div>
      ))}
    </>
  )

  return (
    <div className="stats-bar">
      {items.map(it => (
        <div key={it.l} className="stats-bar-item">
          <span className="stats-bar-v">{it.v}</span>
          <span className="stats-bar-l">{it.l}</span>
        </div>
      ))}
    </div>
  )
}
