import { useState, useEffect } from 'react'
import { usePublicClient } from 'wagmi'
import { useGuestChain } from './useGuestChain.js'
import { VAULT_ABI, SAFE_ABI } from './abi.js'
import { getVaultAddress, getSafeAddress } from './config.js'
import { TOKENS_BY_CHAIN } from './tokenList.js'
import { getChainInfo } from './chainUtils.js'
import { robinhoodChain } from './robinhoodChain.js'

function fmt(wei, dec = 18, digits = 2) {
  const n = Number(wei) / 10 ** dec
  if (n >= 1e6) return (n / 1e6).toFixed(1) + 'M'
  if (n >= 1e3) return (n / 1e3).toFixed(1) + 'K'
  return n.toFixed(digits)
}

const cache = {}

export function useStats(mode) {
  const { activeChainId: chainId } = useGuestChain()
  const publicClient = usePublicClient({ chainId })
  const cacheKey = `${mode}-${chainId}`
  const [stats, setStats] = useState(() => cache[cacheKey] ?? null)

  useEffect(() => {
    if (cache[cacheKey]) setStats(cache[cacheKey])
    else setStats(null)
    const vaultAddress = getVaultAddress(chainId)
    const safeAddress  = getSafeAddress(chainId)
    const tokens = TOKENS_BY_CHAIN[chainId] || TOKENS_BY_CHAIN[robinhoodChain.id]
    const addrs  = tokens.map(t => t.address)
    const { currency } = getChainInfo(chainId)
    if (!publicClient) return
    let cancelled = false
    async function load() {
      try {
        if (mode === 'private') {
          if (!vaultAddress) return
          const [r, leaves] = await Promise.all([
            publicClient.readContract({ address: vaultAddress, abi: VAULT_ABI, functionName: 'getStats', args: [addrs] }),
            publicClient.readContract({ address: vaultAddress, abi: VAULT_ABI, functionName: 'nextIndex' }),
          ])
          const tvl = fmt(r[2][0]) + ' ' + currency
          const totalDeposits = r[3].reduce((a, b) => a + b, 0n)
          const next = { tvl, deposits: totalDeposits.toString(), leaves: leaves.toString() }
          if (!cancelled) { cache[cacheKey] = next; setStats(next) }
        } else {
          if (!safeAddress) return
          const r = await publicClient.readContract({ address: safeAddress, abi: SAFE_ABI, functionName: 'getStats', args: [addrs] })
          const tvl = fmt(r[2][0]) + ' ' + currency
          const totalUsers = r[5]
          const guardianCount = r[6]
          const guardianPct = totalUsers > 0n ? Math.round(Number(guardianCount * 100n / totalUsers)) : 0
          const next = { tvl, users: totalUsers.toString(), guardianPct: guardianPct + '%' }
          if (!cancelled) { cache[cacheKey] = next; setStats(next) }
        }
      } catch { /* RPC error — leave stats null */ }
    }
    load()
    return () => { cancelled = true }
  }, [mode, chainId, publicClient]) // eslint-disable-line

  return stats
}
